package com.explapp.dictionarylegacy;
import android.app.Activity;import android.os.Bundle;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;
public class MainActivity extends Activity{private WebView w;@Override public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);w.setWebChromeClient(new WebChromeClient());w.setWebViewClient(new WebViewClient());w.loadUrl("https://aljwaal1.github.io/Dictforiphone/");}@Override public void onBackPressed(){if(w.canGoBack())w.goBack();else super.onBackPressed();}}
